type EditorialProfile={
  id:string;school:LearningSchool;title:Localized<string>;question:Localized<string>;archetype:LearningArchetype;level:LearningLevel;entities:string[]
  notes:Localized<string[]>;stages:Localized<string[]>;control:{label:Localized<string>;low:Localized<string>;high:Localized<string>}
  sources:LearningSource[];media:[string,string]
}

const l=(en:string,de:string,fr:string,es:string):Localized<string>=>({en,de,fr,es})
const lines=(en:string,de:string,fr:string,es:string):Localized<string[]>=>({en:en.split('§'),de:de.split('§'),fr:fr.split('§'),es:es.split('§')})
const source=(label:string,url:string,en:string,de:string,fr:string,es:string):LearningSource=>({label,url,supports:l(en,de,fr,es)})

