type InteractionKind='annotated-plate'|'process-timeline'|'comparison-lab'|'map-lab'|'sensory-lab'|'simulator'|'decision-case'
type InteractionSeed={prompt:Localized<string>;choices:Localized<string[]>;feedback:Localized<string[]>;prompts?:Partial<Record<InteractionKind,Localized<string>>>;states?:Localized<string[]>;outcomes?:Localized<string[]>}

/* Each masterclass gets a check that tests its own causal model. These are
   kept in the curriculum so translated learners see a real wine question,
   rather than a recycled quiz shell. */
const interactionSeeds:Record<string,InteractionSeed>={
  'wine-as-system':{prompt:l('A young wine is still fermenting. Which observation best tests whether the system is progressing safely?','Ein junger Wein gärt noch. Welche Beobachtung prüft am besten, ob das System sicher voranschreitet?','Un vin jeune fermente encore. Quelle observation vérifie le mieux que le système progresse sans risque ?','Un vino joven sigue fermentando. ¿Qué observación comprueba mejor que el sistema avanza con seguridad?'),choices:lists(['Call it finished when bubbling slows.','Track density and temperature together, then confirm residual sugar.','Choose the aroma that the grape normally promises.'],['Als beendet gelten lassen, sobald die Blasen langsamer werden.','Dichte und Temperatur gemeinsam verfolgen und danach Restzucker bestätigen.','Das Aroma wählen, das die Rebsorte normalerweise verspricht.'],['Le déclarer fini quand les bulles ralentissent.','Suivre ensemble densité et température, puis confirmer les sucres résiduels.','Choisir l’arôme promis par le cépage.'],['Darlo por terminado cuando bajen las burbujas.','Seguir densidad y temperatura juntas y confirmar después el azúcar residual.','Elegir el aroma que normalmente promete la variedad.']),feedback:lists(['Bubbles are an incomplete proxy; gas can stop while sugar or instability remains.','Density, heat and residual sugar separate conversion, temperature and completion instead of treating fermentation as a single signal.','A grape name cannot verify microbial activity or bottle stability.'])},
  'structure-not-flavour':{prompt:l('Two wines smell equally floral. What should you record before deciding which is more balanced?','Zwei Weine riechen gleich blumig. Was solltest du notieren, bevor du entscheidest, welcher ausgewogener wirkt?','Deux vins sentent également la fleur. Que noter avant de décider lequel paraît le plus équilibré ?','Dos vinos huelen igual de florales. ¿Qué debes registrar antes de decidir cuál está más equilibrado?'),choices:lists(['Only the fruit descriptor that comes first.','Map sweetness, acidity, tannin, body and finish through the sip.','Use alcohol as a shortcut for body and balance.'],['Nur den zuerst auftauchenden Fruchtbegriff.','Süße, Säure, Tannin, Körper und Nachhall über den Schluck hinweg erfassen.','Alkohol als Abkürzung für Körper und Balance verwenden.'],['Seulement le descripteur fruité qui vient en premier.','Décrire douceur, acidité, tanins, corps et finale pendant la gorgée.','Prendre l’alcool comme raccourci du corps et de l’équilibre.'],['Solo el descriptor frutal que aparezca primero.','Registrar dulzor, acidez, tanino, cuerpo y final durante el sorbo.','Usar el alcohol como atajo para cuerpo y equilibrio.']),feedback:lists(['Aroma identity says little about the time-course of structure.','A structure map makes the comparison shareable before preference or fruit vocabulary takes over.','Alcohol contributes to weight but cannot stand in for the whole shape of a wine.'])},
  'red-white-rose':{prompt:l('You want a pale rosé from dark-skinned fruit. Which decision controls colour most directly?','Du möchtest einen blassen Rosé aus dunkelschaligen Trauben. Welche Entscheidung steuert die Farbe am direktesten?','Vous voulez un rosé pâle issu de raisins noirs. Quelle décision contrôle directement la couleur ?','Quieres un rosado pálido de uva tinta. ¿Qué decisión controla el color de forma más directa?'),choices:lists(['Ferment the juice with skins until dryness.','Press or separate after a short, observed skin-contact window.','Blend finished red and white wines as the default route.'],['Den Saft bis zur Trockenheit auf den Schalen vergären.','Nach einem kurzen, beobachteten Schalenkontakt pressen oder trennen.','Fertigen Rot- und Weißwein grundsätzlich mischen.'],['Fermenter le jus sur les peaux jusqu’à sec.','Presser ou séparer après un contact bref et observé avec les peaux.','Assembler par défaut un rouge et un blanc finis.'],['Fermentar el mosto con pieles hasta seco.','Prensar o separar tras un contacto breve y observado con las pieles.','Mezclar por defecto vinos tinto y blanco terminados.']),feedback:lists(['Long contact extracts colour and phenolics; it is not the direct route to pale rosé.','Contact time and separation determine how much colour and grip enter before fermentation choices add texture.','Blending is a separate legal and stylistic route, not the defining explanation for classic rosé.'])},
  'vine-anatomy':{prompt:l('A vine faces midday drought. Which response links the leaf to the plant’s carbon budget?','Eine Rebe erlebt mittäglichen Trockenstress. Welche Reaktion verbindet Blatt und Kohlenstoffhaushalt?','Une vigne subit une sécheresse à midi. Quelle réponse relie la feuille au bilan de carbone ?','Una vid sufre sequía al mediodía. ¿Qué respuesta conecta la hoja con el balance de carbono?'),choices:lists(['Roots manufacture sugar while leaves simply store it.','Stomata close to limit water loss, reducing carbon uptake and transpiration.','Berries continue independently because the perennial wood is permanent.'],['Wurzeln stellen Zucker her, während Blätter ihn nur speichern.','Spaltöffnungen schließen gegen Wasserverlust; Kohlenstoffaufnahme und Transpiration sinken.','Beeren arbeiten unabhängig weiter, weil das Dauerholz bleibt.'],['Les racines fabriquent le sucre et les feuilles le stockent seulement.','Les stomates se ferment pour limiter la perte d’eau : assimilation et transpiration diminuent.','Les baies continuent seules puisque le bois est permanent.'],['Las raíces fabrican azúcar y las hojas solo lo almacenan.','Los estomas se cierran para limitar la pérdida de agua y bajan asimilación y transpiración.','Las bayas continúan aparte porque la madera es permanente.']),feedback:lists(['Roots supply water and minerals; leaves do the photosynthetic work.','Stomatal behaviour is the observable link between water status, gas exchange and vine growth.','Permanent wood stores and transports; it does not make berries independent of the canopy.'])},
  'ripeness-harvest':{prompt:l('Sugar has reached its target after a hot week. What is the most defensible next harvest check?','Der Zielzucker ist nach einer heißen Woche erreicht. Was ist der belastbarste nächste Lesetest?','Le sucre cible est atteint après une semaine chaude. Quel contrôle de vendange est le plus défendable ?','El azúcar objetivo se alcanzó tras una semana cálida. ¿Cuál es la siguiente comprobación de vendimia más sólida?'),choices:lists(['Pick immediately because one number defines ripeness.','Resample representative clusters, taste tissues, check acid/pH and read the forecast against the intended style.','Wait for maximum sugar and ignore rain, rot and seed or skin changes.'],['Sofort lesen, weil eine Zahl die Reife definiert.','Repräsentativ nachproben, Gewebe verkosten, Säure/pH prüfen und Wetter sowie Stilziel abgleichen.','Auf maximalen Zucker warten und Regen, Fäulnis sowie Schalen- oder Kernreife ignorieren.'],['Vendanger immédiatement car un chiffre définit la maturité.','Échantillonner à nouveau, goûter les tissus, vérifier acidité/pH et confronter météo et style visé.','Attendre le sucre maximal en ignorant pluie, pourriture et maturité des pépins ou peaux.'],['Vendimiar ya porque un número define la madurez.','Volver a muestrear racimos representativos, probar tejidos, revisar acidez/pH y contrastar previsión y estilo.','Esperar al máximo de azúcar e ignorar lluvia, podredumbre y cambios en piel o semillas.']),feedback:lists(['Brix is a proxy and sampling error can outweigh a daily change.','Harvest is a style-and-risk decision: representative sampling, tissue taste, chemistry and weather belong together.','More hang time can gain flavour while losing crop or freshness to weather and disease.'])},
  'germany-origin':{prompt:l('A German label names a vineyard and a Prädikat. Which reading keeps place and legal category distinct?','Ein deutsches Etikett nennt eine Lage und ein Prädikat. Welche Lesart trennt Ort und Rechtskategorie?','Une étiquette allemande indique un vignoble et un Prädikat. Quelle lecture distingue lieu et catégorie légale ?','Una etiqueta alemana nombra un viñedo y un Prädikat. ¿Qué lectura separa lugar y categoría legal?'),choices:lists(['Treat the Prädikat as a more precise geographic scale.','Read country, region, site and Prädikat as different questions answered by different label terms.','Assume a steep slope guarantees sweetness and quality.'],['Das Prädikat als genauere geografische Ebene lesen.','Land, Gebiet, Lage und Prädikat als verschiedene Fragen und Begriffe lesen.','Annehmen, dass ein Steilhang Süße und Qualität garantiert.'],['Lire le Prädikat comme une échelle géographique plus précise.','Lire pays, région, lieu et Prädikat comme des questions distinctes portées par des termes distincts.','Supposer qu’une pente raide garantit douceur et qualité.'],['Leer el Prädikat como una escala geográfica más precisa.','Leer país, región, parcela y Prädikat como preguntas distintas con términos distintos.','Suponer que una ladera empinada garantiza dulzor y calidad.']),feedback:lists(['A Prädikat is not a map zoom level.','The label can combine legal origin, named place and ripeness/taste category without collapsing them.','Slope changes exposure and work; it cannot guarantee a sensory or quality outcome.'])},
  'wine-faults':{prompt:l('A wine smells muted with a medicinal edge. Which first move protects the diagnosis from a dramatic guess?','Ein Wein riecht gedämpft und leicht medizinisch. Welcher erste Schritt schützt vor einer vorschnellen Diagnose?','Un vin paraît fermé avec une note médicinale. Quel premier geste évite le diagnostic spectaculaire ?','Un vino huele apagado y algo medicinal. ¿Qué primer paso protege de una conjetura dramática?'),choices:lists(['Name Brettanomyces from one descriptor.','Check a clean glass and second sample, then compare air and time while holding two hypotheses.','Add oxygen until the smell disappears and call it cured.'],['Brettanomyces aus einem einzigen Deskriptor benennen.','Sauberes Glas und zweite Probe prüfen, dann Luft und Zeit vergleichen und zwei Hypothesen halten.','Sauerstoff zuführen, bis der Geruch verschwindet, und den Fehler als behoben ansehen.'],['Nommer Brettanomyces à partir d’un seul descripteur.','Vérifier verre propre et seconde bouteille, comparer air et temps en gardant deux hypothèses.','Ajouter de l’oxygène jusqu’à disparition et déclarer le défaut corrigé.'],['Nombrar Brettanomyces por un solo descriptor.','Comprobar copa limpia y segunda muestra, comparar aire y tiempo manteniendo dos hipótesis.','Añadir oxígeno hasta que desaparezca y darlo por corregido.']),feedback:lists(['A descriptor is evidence, not an organism or concentration.','Controls, time and a second sample distinguish contamination, reduction, oxidation and volatile phenols more safely.','Air is a test; some sulfur compounds transform while others persist or worsen.'])},
  'pairing-balance':{prompt:l('A spicy dish is sweeter than the wine. What change should you predict and test first?','Ein scharfes Gericht ist süßer als der Wein. Welche Veränderung solltest du zuerst erwarten und prüfen?','Un plat épicé est plus doux que le vin. Quel changement prévoir et tester d’abord ?','Un plato picante es más dulce que el vino. ¿Qué cambio debes prever y probar primero?'),choices:lists(['The wine will taste fruitier and more generous.','The wine can taste leaner and more acidic; compare with a less-sweet bite while holding the wine constant.','Sweetness never changes a wine’s balance at the table.'],['Der Wein schmeckt fruchtiger und großzügiger.','Der Wein kann schlanker und säurebetonter wirken; mit einem weniger süßen Bissen vergleichen.','Süße verändert die Balance am Tisch nie.'],['Le vin paraîtra plus fruité et généreux.','Le vin peut paraître plus maigre et acide ; comparer avec une bouchée moins douce.','La douceur ne change jamais l’équilibre d’un vin à table.'],['El vino sabrá más frutal y generoso.','Puede parecer más delgado y ácido; compáralo con un bocado menos dulce.','El dulzor nunca cambia el equilibrio de un vino en la mesa.']),feedback:lists(['Heat and fruit can shift perception, but sweetness is the clean first variable to test.','Relative sweetness is a balance condition; a controlled second bite makes the direction observable.','Pairing effects are contextual, not absent.'])},
  'build-a-tasting-note':{prompt:l('You will reopen the bottle in six months. Which note will still help you?','Du öffnest die Flasche in sechs Monaten erneut. Welche Notiz hilft dir dann noch?','Vous rouvrirez la bouteille dans six mois. Quelle note restera utile ?','Abrirás la botella de nuevo en seis meses. ¿Qué nota seguirá ayudándote?'),choices:lists(['A long list of impressive fruit names with no conditions.','Separate observation, inference and preference, then record a change and a next action.','A score alone, without serving temperature or time.'],['Eine lange Liste eindrucksvoller Fruchtnamen ohne Bedingungen.','Beobachtung, Deutung und Vorliebe trennen und Veränderung sowie nächste Handlung notieren.','Nur eine Punktzahl ohne Temperatur oder Zeit.'],['Une longue liste de fruits sans conditions.','Séparer observation, inférence et préférence, puis noter évolution et prochaine action.','Une note seule, sans température ni durée.'],['Una lista larga de frutas sin condiciones.','Separar observación, inferencia y preferencia, y anotar cambio y siguiente acción.','Solo una puntuación, sin temperatura ni tiempo.']),feedback:lists(['Descriptors without context are difficult to compare later.','A useful note records conditions, structure, change, uncertainty and what to do next.','A score hides the evidence that makes a future tasting comparable.'])},
  'producer-story-chain':{prompt:l('You are hosting a blind first pour. Which reveal order connects a producer to evidence without leading the room?','Du leitest einen ersten blinden Ausschank. Welche Reihenfolge verbindet Erzeuger und Evidenz, ohne die Runde zu lenken?','Vous animez un premier service à l’aveugle. Quel ordre relie domaine et indices sans orienter la salle ?','Guías un primer servicio a ciegas. ¿Qué orden conecta productor y evidencia sin dirigir a la sala?'),choices:lists(['Tell the full biography before anyone tastes.','Ask for an observation, reveal place and constraint, then the decision and return to the glass.','Name the expected aroma and ask guests to find it.'],['Die ganze Biografie vor dem Probieren erzählen.','Beobachtung erfragen, Ort und Einschränkung zeigen, dann Entscheidung und zurück ins Glas.','Das erwartete Aroma nennen und die Gäste danach suchen lassen.'],['Raconter toute la biographie avant de goûter.','Demander une observation, révéler lieu et contrainte, puis décision et retour au verre.','Nommer l’arôme attendu et demander de le retrouver.'],['Contar toda la biografía antes de probar.','Pedir una observación, revelar lugar y restricción, luego decisión y volver a la copa.','Nombrar el aroma esperado y pedir que lo encuentren.']),feedback:lists(['Biography first can create expectation before evidence.','A reveal ladder lets the room test each claim and keeps the maker’s constraint meaningful.','Leading with an aroma turns a hypothesis into a demand.'])},
  fermentation:{prompt:l('Density has barely moved for two days. Which evidence should guide the next cellar decision?','Die Dichte hat sich zwei Tage kaum verändert. Welche Evidenz sollte die nächste Kellerentscheidung leiten?','La densité a à peine bougé depuis deux jours. Quels indices guideront la prochaine décision de cave ?','La densidad apenas cambia desde hace dos días. ¿Qué evidencia debe guiar la siguiente decisión de bodega?'),choices:lists(['Warm the tank immediately, without checking the analysis.','Verify measurement, temperature, yeast nutrition, ethanol and residual sugars before choosing an intervention.','Add nutrients by rule because every slow ferment lacks nitrogen.'],['Den Tank sofort wärmen, ohne die Analyse zu prüfen.','Messung, Temperatur, Hefenährstoffe, Ethanol und Restzucker prüfen, bevor du eingreifst.','Nach Regel Nährstoffe zugeben, weil jede langsame Gärung Stickstoffmangel hat.'],['Réchauffer la cuve sans vérifier l’analyse.','Vérifier mesure, température, nutrition, éthanol et sucres résiduels avant toute intervention.','Ajouter des nutriments par principe car toute fermentation lente manque d’azote.'],['Calentar el depósito sin revisar el análisis.','Verificar medición, temperatura, nutrientes, etanol y azúcares residuales antes de intervenir.','Añadir nutrientes por norma porque toda fermentación lenta carece de nitrógeno.']),feedback:lists(['Heat may help or harm; without diagnosis it is an uncontrolled change.','A stalled ferment is a diagnosis problem: measurement and multiple constraints come before a remedy.','Nitrogen can be limiting, but blind additions ignore timing, dose, legal limits and other inhibitors.'])},
}
const promptSet=(focus:Localized<string>,mapFocus=focus,stageFocus=focus):Partial<Record<InteractionKind,Localized<string>>>=>({
  'comparison-lab':l(`Change ${focus.en} one step and compare the likely consequence in the glass.`,`Verändere ${focus.de} um eine Stufe und vergleiche die wahrscheinliche Folge im Glas.`,`Modifiez ${focus.fr} d’un cran et comparez la conséquence probable dans le verre.`,`Cambia ${focus.es} un paso y compara la consecuencia probable en la copa.`),
  'sensory-lab':l(`Taste for the sensory effect of ${focus.en}; record the observation before naming a cause.`,`Verkoste die sensorische Folge von ${focus.de}; notiere den Befund, bevor du eine Ursache nennst.`,`Goûtez l’effet sensoriel de ${focus.fr} ; notez l’observation avant d’en nommer la cause.`,`Prueba el efecto sensorial de ${focus.es}; registra la observación antes de nombrar una causa.`),
  simulator:l(`Set ${focus.en} deliberately, then check which measurement or sensation should move first.`,`Stelle ${focus.de} bewusst ein und prüfe, welche Messung oder Empfindung sich zuerst ändern sollte.`,`Réglez ${focus.fr} volontairement, puis vérifiez quelle mesure ou sensation devrait changer d’abord.`,`Ajusta ${focus.es} de forma deliberada y comprueba qué medida o sensación debería cambiar primero.`),
  'process-timeline':l(`Follow the stages to see how ${stageFocus.en} changes the material from one step to the next.`,`Folge den Phasen und beobachte, wie ${stageFocus.de} das Material von Schritt zu Schritt verändert.`,`Suivez les étapes pour voir comment ${stageFocus.fr} transforme la matière d’une étape à l’autre.`,`Sigue las etapas para ver cómo ${stageFocus.es} cambia la materia de un paso al siguiente.`),
  'annotated-plate':l(`Select one part of the illustration and connect it to the next observable effect of ${stageFocus.en}.`,`Wähle einen Teil der Abbildung und verbinde ihn mit der nächsten beobachtbaren Folge von ${stageFocus.de}.`,`Choisissez une partie de l’illustration et reliez-la à l’effet observable suivant de ${stageFocus.fr}.`,`Elige una parte de la ilustración y relaciónala con el siguiente efecto observable de ${stageFocus.es}.`),
  'map-lab':l(`Move through ${mapFocus.en} one level at a time; each level answers a different question.`,`Gehe ${mapFocus.de} Ebene für Ebene durch; jede Ebene beantwortet eine andere Frage.`,`Parcourez ${mapFocus.fr} niveau par niveau ; chaque niveau répond à une question différente.`,`Recorre ${mapFocus.es} nivel a nivel; cada nivel responde a una pregunta distinta.`),
  'decision-case':l(`Open one clue at a time and decide what ${stageFocus.en} supports before you make a conclusion.`,`Öffne einen Hinweis nach dem anderen und entscheide, was ${stageFocus.de} belegt, bevor du schließt.`,`Ouvrez un indice à la fois et décidez ce que ${stageFocus.fr} permet d’affirmer avant de conclure.`,`Abre una pista cada vez y decide qué demuestra ${stageFocus.es} antes de concluir.`),
})

const controlStates:Record<string,Localized<string[]>>={
  'wine-as-system':lists(
    ['Slow conversion leaves more time for observation, but density and temperature still need checking.','A moderate rate keeps heat and nutrient demand readable; compare density trend with residual sugar.','Fast conversion raises heat and nutrient stress; cooling and checks protect yeast and completion.'],
    ['Langsame Umwandlung lässt mehr Zeit zur Beobachtung, doch Dichte und Temperatur müssen weiter geprüft werden.','Ein mittleres Tempo macht Wärme und Nährstoffbedarf lesbar; vergleiche Dichteverlauf und Restzucker.','Schnelle Umwandlung erhöht Wärme- und Nährstoffstress; Kühlung und Kontrollen schützen Hefe und Abschluss.'],
    ['Une transformation lente laisse du temps pour observer, mais densité et température restent à suivre.','Un rythme modéré rend chaleur et besoin nutritif lisibles ; comparez densité et sucres résiduels.','Une transformation rapide accroît chaleur et stress nutritif ; refroidissement et contrôles protègent levures et fin de fermentation.'],
    ['Una transformación lenta deja tiempo para observar, pero hay que revisar densidad y temperatura.','Un ritmo moderado hace visibles calor y demanda nutritiva; compara densidad y azúcar residual.','Una transformación rápida aumenta calor y estrés nutritivo; enfriar y controlar protege levaduras y finalización.']),
  'structure-not-flavour':lists(
    ['Cooler service tightens acidity and quiets aroma release; taste again before calling the wine thin.','A middle temperature lets structure and aroma arrive together; record attack, middle and finish.','Warmer service broadens aroma and can expose alcohol or softness; separate release from balance.'],
    ['Kühler Service strafft Säure und dämpft Duft; probiere erneut, bevor du den Wein dünn nennst.','Mittlere Temperatur lässt Struktur und Duft gemeinsam erscheinen; notiere Auftakt, Mitte und Nachhall.','Wärmerer Service öffnet den Duft und kann Alkohol oder Weichheit zeigen; trenne Freisetzung von Balance.'],
    ['Un service plus frais resserre l’acidité et calme les arômes ; regoûtez avant de conclure à la maigreur.','Une température intermédiaire laisse structure et arômes arriver ensemble ; notez attaque, milieu et finale.','Un service plus chaud élargit le nez et peut révéler alcool ou souplesse ; séparez libération et équilibre.'],
    ['Un servicio más frío tensa la acidez y calma el aroma; vuelve a probar antes de llamarlo delgado.','Una temperatura media deja llegar estructura y aroma juntos; registra ataque, centro y final.','Un servicio más cálido abre el aroma y puede mostrar alcohol o blandura; separa liberación y equilibrio.']),
  'red-white-rose':lists(
    ['Immediate pressing limits colour and phenolic pickup; check juice tone and grip rather than assuming neutrality.','A short contact window adds measured colour and texture; taste the press fraction before extending it.','Extended contact raises colour and grip but also extraction risk; temperature and seed maturity matter.'],
    ['Sofortpressung begrenzt Farbe und Phenole; prüfe Mostfarbe und Griff statt Neutralität anzunehmen.','Ein kurzes Kontaktfenster bringt dosiert Farbe und Textur; verkoste die Pressfraktion vor einer Verlängerung.','Längerer Kontakt erhöht Farbe und Griff, aber auch Extraktionsrisiko; Temperatur und Kernreife zählen.'],
    ['Le pressurage immédiat limite couleur et phénols ; observez teinte et prise sans supposer la neutralité.','Un contact bref ajoute couleur et texture de façon mesurée ; goûtez la fraction de presse avant de prolonger.','Un contact long augmente couleur et prise mais aussi le risque d’extraction ; température et maturité des pépins comptent.'],
    ['El prensado inmediato limita color y fenoles; observa tono y agarre sin suponer neutralidad.','Un contacto breve añade color y textura de forma medida; prueba la fracción de prensa antes de alargarlo.','Un contacto largo eleva color y agarre, pero también el riesgo de extracción; importan temperatura y madurez de semillas.']),
  'vine-anatomy':lists(
    ['Closed stomata conserve water but reduce carbon uptake; inspect leaf temperature and growth before judging vigour.','Balanced water status supports gas exchange without proving constant access; compare soil, canopy and weather.','Open stomata support photosynthesis while increasing water loss; heat and wind can reverse the benefit.'],
    ['Geschlossene Spaltöffnungen sparen Wasser, senken aber Kohlenstoffaufnahme; prüfe Blatttemperatur und Wachstum.','Ausgeglichener Wasserstatus unterstützt Gasaustausch, beweist aber keinen ständigen Zugang; vergleiche Boden, Laub und Wetter.','Offene Spaltöffnungen unterstützen Photosynthese und erhöhen Wasserverlust; Hitze und Wind können den Vorteil umkehren.'],
    ['Des stomates fermés économisent l’eau mais réduisent l’assimilation ; observez température foliaire et croissance.','Un état hydrique équilibré soutient les échanges sans prouver un accès constant ; comparez sol, feuillage et météo.','Des stomates ouverts soutiennent la photosynthèse mais augmentent la perte d’eau ; chaleur et vent peuvent inverser le bénéfice.'],
    ['Los estomas cerrados ahorran agua pero reducen asimilación; observa temperatura de hoja y crecimiento.','Un estado hídrico equilibrado sostiene el intercambio sin probar acceso constante; compara suelo, vegetación y clima.','Los estomas abiertos sostienen fotosíntesis pero aumentan pérdida de agua; calor y viento pueden invertir el beneficio.']),
  'ripeness-harvest':lists(
    ['Earlier harvest protects acidity and weather risk, but tissue flavour and intended style still decide the date.','A middle hang-time window balances sugar, acidity, tissue maturity and forecast; resample rather than trust one number.','Later harvest may deepen flavour or soften phenolics, but heat, rain, rot and shrivel can erase the gain.'],
    ['Frühere Lese schützt Säure und vor Wetterrisiko, doch Gewebereife und Stilziel bestimmen weiter den Termin.','Ein mittleres Fenster balanciert Zucker, Säure, Gewebereife und Wetter; nachproben statt einer Zahl vertrauen.','Spätere Lese kann Aroma vertiefen oder Phenole abrunden, doch Hitze, Regen, Fäulnis und Schrumpfung können den Gewinn aufzehren.'],
    ['Une récolte plus précoce protège acidité et risque météo, mais maturité des tissus et style visé restent décisifs.','Une fenêtre intermédiaire équilibre sucre, acidité, tissus et prévisions ; rééchantillonnez plutôt que croire un chiffre.','Attendre peut approfondir les arômes ou assouplir les phénols, mais chaleur, pluie, botrytis et flétrissement peuvent annuler le gain.'],
    ['Una vendimia temprana protege acidez y riesgo meteorológico, pero mandan madurez de tejidos y estilo.','Una ventana intermedia equilibra azúcar, acidez, tejidos y previsión; vuelve a muestrear en vez de confiar en un número.','Esperar puede profundizar aromas o suavizar fenoles, pero calor, lluvia, botritis y pasificación pueden borrar la ganancia.']),
  'germany-origin':lists(
    ['Shaded exposure usually slows heat accumulation; compare slope, wind and actual vine temperature before inferring ripeness.','Open exposure can balance light and cooling; aspect and canopy still decide the parcel’s microclimate.','Sun-facing slope raises heat and light load, which can accelerate ripening or sunburn; retain canopy and monitor berries.'],
    ['Schattige Exposition verlangsamt meist die Wärmesumme; vergleiche Hang, Wind und Rebstocktemperatur vor einer Reifeschlussfolgerung.','Offene Exposition kann Licht und Kühlung ausgleichen; Ausrichtung und Laubwand bestimmen weiterhin das Mikroklima.','Sonnenzugewandte Hänge erhöhen Wärme- und Lichtlast; Reife kann schneller gehen oder Sonnenbrand drohen, daher Laub erhalten und Beeren prüfen.'],
    ['Une exposition ombragée ralentit souvent l’accumulation de chaleur ; comparez pente, vent et température réelle avant de juger la maturité.','Une exposition ouverte peut équilibrer lumière et fraîcheur ; orientation et feuillage déterminent encore le microclimat.','Une pente tournée au soleil augmente chaleur et lumière ; la maturité peut accélérer ou brûler, donc gardez du feuillage et surveillez les baies.'],
    ['Una exposición sombre suele ralentizar la acumulación de calor; compara pendiente, viento y temperatura real antes de inferir madurez.','Una exposición abierta puede equilibrar luz y frescor; orientación y vegetación siguen decidiendo el microclima.','Una ladera soleada aumenta calor y luz; puede acelerar madurez o causar quemadura, así que conserva hojas y vigila las bayas.']),
  'wine-faults':lists(
    ['An opening snapshot is evidence only; check a clean glass and second sample before naming a fault.','A short, controlled air comparison separates a reversible smell from a persistent taint; record both hypotheses.','Persistent or transformed evidence after air needs another sample and history; oxygen is a test, not a cure.'],
    ['Der Moment beim Öffnen ist nur ein Befund; prüfe sauberes Glas und zweite Probe vor der Fehlerdiagnose.','Ein kurzer, kontrollierter Luftvergleich trennt veränderlichen Geruch von bleibendem Fehler; notiere beide Hypothesen.','Bleibende oder veränderte Evidenz nach Luftkontakt verlangt eine weitere Probe und Historie; Sauerstoff ist ein Test, keine Heilung.'],
    ['L’instant de l’ouverture n’est qu’un indice ; vérifiez verre propre et seconde bouteille avant de nommer un défaut.','Une courte comparaison à l’air distingue odeur réversible et déviation persistante ; notez les deux hypothèses.','Un indice persistant ou transformé après l’air demande un autre échantillon et l’historique ; l’oxygène est un test, pas un remède.'],
    ['La impresión al abrir es solo evidencia; revisa copa limpia y segunda muestra antes de nombrar un defecto.','Una comparación breve y controlada con aire separa olor reversible de defecto persistente; registra ambas hipótesis.','La evidencia persistente o transformada tras el aire pide otra muestra e historial; el oxígeno es una prueba, no una cura.']),
  'pairing-balance':lists(
    ['When wine matches or exceeds food sweetness, acidity and fruit stay more proportionate; test the bite before judging the bottle.','A near-equal match lets salt, fat and acid shape the result; change one food variable at a time.','Sweeter food can make wine seem leaner, sharper and more bitter; adjust the dish or choose a sweeter wine.'],
    ['Wenn der Wein gleich süß oder süßer ist, bleiben Säure und Frucht eher im Verhältnis; prüfe den Bissen vor dem Urteil.','Bei ähnlicher Süße formen Salz, Fett und Säure das Ergebnis; verändere jeweils nur eine Speisevariable.','Süßere Speise kann den Wein schlanker, schärfer und bitterer wirken lassen; passe Gericht oder Wein an.'],
    ['Quand le vin égale ou dépasse la douceur du mets, acidité et fruit restent plus proportionnés ; testez la bouchée avant de juger.','Un accord proche laisse sel, gras et acidité façonner le résultat ; ne changez qu’une variable alimentaire à la fois.','Un mets plus doux peut rendre le vin maigre, plus vif et amer ; ajustez le plat ou choisissez un vin plus doux.'],
    ['Cuando el vino iguala o supera el dulzor del plato, acidez y fruta guardan mejor proporción; prueba el bocado antes de juzgar.','Un ajuste cercano deja que sal, grasa y acidez formen el resultado; cambia una sola variable del alimento.','Un plato más dulce puede volver el vino delgado, afilado y amargo; ajusta el plato o elige un vino más dulce.']),
  'build-a-tasting-note':lists(
    ['At opening, record condition and first shape; a baseline makes later change visible.','After some time, aroma may open while structure shifts; compare the same glass before adding a cause.','Later evolution is useful only when it leads to an action such as serving, pairing or retasting.'],
    ['Beim Öffnen notierst du Zustand und erste Form; eine Ausgangslinie macht spätere Veränderung sichtbar.','Nach einiger Zeit kann sich Duft öffnen, während Struktur wechselt; vergleiche dasselbe Glas, bevor du eine Ursache nennst.','Spätere Entwicklung ist erst dann nützlich, wenn sie zu einer Handlung führt: servieren, kombinieren oder nachprobieren.'],
    ['À l’ouverture, notez état et première forme ; cette base rend le changement visible plus tard.','Avec le temps, le nez peut s’ouvrir tandis que la structure change ; comparez le même verre avant d’attribuer une cause.','L’évolution ne devient utile que si elle conduit à une action : servir, accorder ou regoûter.'],
    ['Al abrir, registra estado y primera forma; esa base hace visible el cambio posterior.','Con el tiempo el aroma puede abrirse mientras cambia la estructura; compara la misma copa antes de atribuir una causa.','La evolución solo sirve si lleva a una acción: servir, maridar o volver a probar.']),
  'producer-story-chain':lists(
    ['A blind first pour protects observation from biography; ask what is in the glass before telling the story.','A staged reveal links place and constraint to one decision, leaving room to test the claim.','A full story first can lead expectation; compare the predicted effect with the actual glass.'],
    ['Ein blinder erster Ausschank schützt die Beobachtung vor Biografie; frage zuerst, was im Glas ist.','Eine gestufte Enthüllung verbindet Ort und Einschränkung mit einer Entscheidung und lässt die Behauptung prüfen.','Die ganze Geschichte zuerst lenkt Erwartungen; vergleiche die Vorhersage mit dem tatsächlichen Glas.'],
    ['Un premier service à l’aveugle protège l’observation de la biographie ; demandez d’abord ce qui est dans le verre.','Une révélation graduelle relie lieu et contrainte à une décision que l’on peut vérifier.','Raconter toute l’histoire d’abord oriente l’attente ; comparez la prédiction au verre réel.'],
    ['Un primer servicio a ciegas protege la observación de la biografía; pregunta primero qué hay en la copa.','Una revelación por etapas conecta lugar y restricción con una decisión que se puede comprobar.','Contar toda la historia primero dirige expectativas; compara la predicción con la copa real.']),
  fermentation:lists(
    ['Cool fermentation preserves volatile aroma and slows kinetics; verify progress rather than calling a quiet tank finished.','A moderate temperature balances yeast growth, heat and aroma; track density and temperature together.','Warm fermentation can accelerate conversion but raise heat and volatile loss; intervene only after diagnosis.'],
    ['Kühle Gärung schützt flüchtige Aromen und verlangsamt Kinetik; prüfe den Verlauf statt einen stillen Tank als fertig anzusehen.','Mittlere Temperatur balanciert Hefewachstum, Wärme und Duft; verfolge Dichte und Temperatur gemeinsam.','Warme Gärung kann Umwandlung beschleunigen, aber Wärme und Aromaverlust erhöhen; greife erst nach Diagnose ein.'],
    ['Une fermentation fraîche préserve les arômes volatils et ralentit la cinétique ; vérifiez l’avancement avant de conclure.','Une température intermédiaire équilibre croissance des levures, chaleur et arômes ; suivez densité et température ensemble.','Une fermentation chaude peut accélérer la conversion mais accroître chaleur et pertes volatiles ; intervenez après diagnostic.'],
    ['Una fermentación fresca conserva aromas volátiles y ralentiza la cinética; revisa el avance antes de darla por terminada.','Una temperatura media equilibra crecimiento de levaduras, calor y aroma; sigue densidad y temperatura juntas.','Una fermentación cálida puede acelerar conversión, pero aumentar calor y pérdida volátil; intervén tras diagnosticar.']),
}

const stageOutcomes:Record<string,Localized<string[]>>={
  'wine-as-system':lists(
    ['Berry compartments bring different sugar, acid, nitrogen and phenolic loads into the cellar.','Crushing starts skin–juice contact; oxygen, enzymes and temperature can alter browning before fermentation.','Yeast converts sugar to ethanol, carbon dioxide and heat; density plus temperature reveal progress.','Lees, bacteria, oxygen and vessel permeability keep changing texture after sugar falls.','Closure exchange changes gas and aroma over time; test a style claim against a glass observation.'],
    ['Beerenteile bringen unterschiedliche Mengen an Zucker, Säure, Stickstoff und Phenolen in den Keller.','Quetschen startet den Kontakt von Schale und Saft; Sauerstoff, Enzyme und Temperatur können vor der Gärung Bräunung verändern.','Hefe wandelt Zucker in Ethanol, Kohlendioxid und Wärme um; Dichte und Temperatur zeigen den Verlauf.','Hefe, Bakterien, Sauerstoff und Gefäßdurchlässigkeit verändern Textur weiter, nachdem Zucker sinkt.','Der Verschluss verändert Gas und Duft über die Zeit; prüfe Stilbehauptungen an einer Beobachtung im Glas.'],
    ['Les compartiments de la baie apportent au chai des charges différentes en sucre, acides, azote et phénols.','Le foulage lance le contact peau-jus ; oxygène, enzymes et température peuvent modifier le brunissement avant la fermentation.','Les levures transforment sucre en éthanol, gaz carbonique et chaleur ; densité et température montrent l’avancement.','Lies, bactéries, oxygène et perméabilité du contenant continuent de changer la texture après la baisse des sucres.','Le bouchage modifie gaz et arômes avec le temps ; confrontez une affirmation de style au verre.'],
    ['Los compartimentos de la baya llevan al sótano cargas distintas de azúcar, ácidos, nitrógeno y fenoles.','El estrujado inicia el contacto piel-zumo; oxígeno, enzimas y temperatura pueden cambiar el pardeamiento antes de fermentar.','La levadura convierte azúcar en etanol, dióxido de carbono y calor; densidad y temperatura muestran el avance.','Lías, bacterias, oxígeno y permeabilidad del recipiente siguen cambiando textura cuando baja el azúcar.','El cierre cambia gas y aroma con el tiempo; contrasta una afirmación de estilo con una observación en copa.']),
  'structure-not-flavour':lists(
    ['Sweetness and acidity set the opening line; temperature can sharpen or soften that first impression.','Tannin shows as grip, drying or bitterness; skin, seed, oak and saliva alter its texture.','Alcohol adds warmth, but extract, sugar, glycerol and acidity also build body.','Gas and serving temperature change aroma release, lift and tactile pressure.','Length is the return after the sip; compare attack, middle and finish before calling balance.'],
    ['Süße und Säure setzen die Auftaktlinie; Temperatur kann diesen ersten Eindruck schärfen oder mildern.','Tannin zeigt sich als Griff, Trockenheit oder Bitterkeit; Schale, Kern, Holz und Speichel verändern die Textur.','Alkohol bringt Wärme, doch Extrakt, Zucker, Glycerin und Säure bilden ebenfalls Körper.','Gas und Serviertemperatur verändern Duftfreisetzung, Spannung und Druck am Gaumen.','Länge ist das Zurückkehren nach dem Schluck; vergleiche Auftakt, Mitte und Nachhall vor dem Balanceurteil.'],
    ['Douceur et acidité dessinent l’attaque ; la température peut accentuer ou adoucir cette première impression.','Le tanin se manifeste par prise, sécheresse ou amertume ; peau, pépin, bois et salive changent son toucher.','L’alcool apporte chaleur, mais extrait, sucre, glycérol et acidité construisent aussi le corps.','Gaz et température de service modifient libération des arômes, tension et pression tactile.','La longueur est le retour après la gorgée ; comparez attaque, milieu et finale avant de juger l’équilibre.'],
    ['Dulzor y acidez forman el ataque; la temperatura puede afilar o suavizar esa primera impresión.','El tanino aparece como agarre, sequedad o amargor; piel, semilla, roble y saliva cambian su textura.','El alcohol aporta calor, pero extracto, azúcar, glicerol y acidez también forman cuerpo.','Gas y temperatura de servicio cambian liberación aromática, tensión y presión táctil.','La longitud es lo que vuelve tras el sorbo; compara ataque, centro y final antes de juzgar equilibrio.']),
  'red-white-rose':lists(
    ['Sorting separates sound fruit from damaged fruit; it changes the material before colour decisions begin.','Pressing or crushing sets the solids and juice relationship that extraction will act on.','The contact window controls how much colour and phenolic grip enter the juice.','Fermentation route adds heat, mixing and time, so colour alone cannot identify style.','Separation and élevage decide whether freshness, grip and texture integrate before bottling.'],
    ['Sortieren trennt gesundes von beschädigtem Lesegut; damit verändert sich das Material vor der Farbentscheidung.','Pressen oder Quetschen legt das Verhältnis von Feststoffen und Saft fest, auf das Extraktion wirkt.','Das Kontaktfenster steuert, wie viel Farbe und phenolischer Griff in den Saft gelangen.','Der Gärweg bringt Wärme, Bewegung und Zeit ein; Farbe allein erkennt daher keinen Stil.','Trennung und Ausbau entscheiden, ob Frische, Griff und Textur vor der Abfüllung zusammenfinden.'],
    ['Le tri sépare les raisins sains des raisins altérés ; la matière change avant les choix de couleur.','Pressurage ou foulage fixe le rapport entre solides et jus sur lequel agira l’extraction.','La fenêtre de contact contrôle la quantité de couleur et de prise phénolique qui entre dans le jus.','La voie fermentaire ajoute chaleur, mouvements et temps ; la couleur seule n’identifie donc pas le style.','Séparation et élevage décident de l’intégration de fraîcheur, prise et texture avant la mise.'],
    ['La selección separa uva sana de uva dañada; la materia cambia antes de decidir el color.','Prensar o estrujar fija la relación entre sólidos y mosto sobre la que actuará la extracción.','La ventana de contacto controla cuánto color y agarre fenólico entra en el mosto.','La ruta de fermentación añade calor, movimiento y tiempo; el color solo no identifica el estilo.','Separación y crianza deciden si frescura, agarre y textura se integran antes de embotellar.']),
  'vine-anatomy':lists(
    ['Roots explore pores and fractures; water access depends on profile, depth, oxygen and season, not depth alone.','Trunk and cordons transport and store; xylem carries water while phloem distributes sugars and signals.','Buds hold future shoots and clusters; pruning leaves a plan, but frost and reserves decide survival.','Leaves trade water for carbon through stomata; heat, wind and vine status change that exchange hourly.','Clusters and berries ripen as tissues: pulp, skin and seeds follow different clocks and evidence.'],
    ['Wurzeln erkunden Poren und Klüfte; Wasserzugang hängt von Profil, Tiefe, Sauerstoff und Saison ab, nicht nur von Tiefe.','Stamm und Kordons transportieren und speichern; Xylem führt Wasser, Phloem verteilt Zucker und Signale.','Knospen enthalten künftige Triebe und Trauben; Schnitt legt einen Plan an, Frost und Reserven entscheiden über Überleben.','Blätter tauschen über Spaltöffnungen Wasser gegen Kohlenstoff; Hitze, Wind und Wasserstatus ändern das stündlich.','Trauben und Beeren reifen als Gewebe: Fruchtfleisch, Schale und Kerne folgen verschiedenen Uhren und Befunden.'],
    ['Les racines explorent pores et fissures ; l’accès à l’eau dépend du profil, profondeur, oxygène et saison, pas de la profondeur seule.','Tronc et cordons transportent et stockent ; xylème monte l’eau, phloème distribue sucres et signaux.','Les bourgeons portent futurs rameaux et grappes ; la taille prépare, mais gel et réserves décident de la survie.','Les feuilles échangent eau et carbone par les stomates ; chaleur, vent et état hydrique changent cet échange chaque heure.','Grappes et baies mûrissent par tissus : pulpe, peau et pépins suivent des rythmes et indices différents.'],
    ['Las raíces exploran poros y grietas; el acceso al agua depende de perfil, profundidad, oxígeno y estación, no solo de profundidad.','Tronco y brazos transportan y almacenan; xilema lleva agua y floema distribuye azúcares y señales.','Las yemas contienen futuros brotes y racimos; la poda planifica, pero helada y reservas deciden la supervivencia.','Las hojas intercambian agua por carbono mediante estomas; calor, viento y estado hídrico cambian ese intercambio cada hora.','Racimos y bayas maduran como tejidos: pulpa, piel y semillas siguen relojes y evidencias distintos.']),
  'ripeness-harvest':lists(
    ['Representative sampling reduces row and cluster bias; the sample is part of the measurement.','Sugar estimates concentration and potential alcohol, not flavour maturity or risk by itself.','Acidity and pH move on related but different paths; measure both before setting a date.','Skin, seed, pulp and aroma maturity need tasting alongside analysis.','Weather, disease, labour and intended style turn harvest into a risk decision, not a maximum-sugar race.'],
    ['Repräsentative Proben verringern Reihen- und Traubenbias; die Probe gehört zur Messung.','Zucker schätzt Konzentration und möglichen Alkohol, aber nicht allein Aromareife oder Risiko.','Säure und pH entwickeln sich verbunden, aber nicht gleich; miss beides vor der Terminwahl.','Reife von Schale, Kern, Fruchtfleisch und Aroma muss neben Analysen verkostet werden.','Wetter, Krankheit, Arbeit und Stilziel machen die Lese zu einer Risikoentscheidung, nicht zum Wettlauf um Maximalzucker.'],
    ['Un échantillonnage représentatif réduit le biais des rangs et grappes ; l’échantillon fait partie de la mesure.','Le sucre estime concentration et alcool potentiel, pas à lui seul maturité aromatique ou risque.','Acidité et pH évoluent ensemble sans être des miroirs ; mesurez les deux avant de fixer la date.','Maturité de peau, pépin, pulpe et arôme se goûtent avec les analyses.','Météo, maladie, main-d’œuvre et style visé font de la vendange une décision de risque, pas une course au sucre maximal.'],
    ['Un muestreo representativo reduce sesgo de filas y racimos; la muestra forma parte de la medida.','El azúcar estima concentración y alcohol potencial, no por sí solo madurez aromática o riesgo.','Acidez y pH evolucionan relacionados pero no iguales; mide ambos antes de fijar fecha.','La madurez de piel, semilla, pulpa y aroma se prueba junto con el análisis.','Clima, enfermedad, mano de obra y estilo convierten la vendimia en una decisión de riesgo, no una carrera por el máximo azúcar.']),
  'germany-origin':lists(
    ['Country and the thirteen regions establish broad legal origin; they do not describe one slope or soil.','Mosel or Rheingau narrows the river context, but aspect, altitude, wind and parcel still vary.','Village and Bereich refine origin; they remain different questions from a named vineyard or taste term.','A named vineyard identifies a site within the legal hierarchy; producer and vintage still matter.','Prädikat and finished taste terms describe harvest material or sweetness style, not a map zoom level.'],
    ['Land und dreizehn Anbaugebiete setzen die breite rechtliche Herkunft; sie beschreiben keinen einzelnen Hang oder Boden.','Mosel oder Rheingau verengt den Flusskontext, doch Ausrichtung, Höhe, Wind und Lage variieren weiter.','Ort und Bereich verfeinern Herkunft; sie sind andere Fragen als eine benannte Lage oder ein Geschmacksterm.','Eine benannte Lage bezeichnet einen Ort innerhalb der Hierarchie; Erzeuger und Jahrgang zählen weiterhin.','Prädikat und fertige Geschmacksterme beschreiben Lesegut oder Süßestil, keine Kartenzoomstufe.'],
    ['Pays et treize régions établissent l’origine légale générale ; ils ne décrivent ni une pente ni un sol uniques.','Moselle ou Rheingau resserre le contexte fluvial, mais orientation, altitude, vent et parcelle varient encore.','Village et Bereich précisent l’origine ; ce sont d’autres questions qu’un vignoble nommé ou un terme de goût.','Un vignoble nommé identifie un site dans la hiérarchie légale ; producteur et millésime comptent toujours.','Prädikat et termes de douceur décrivent matière de récolte ou style sucré, pas un niveau de zoom cartographique.'],
    ['País y trece regiones establecen origen legal amplio; no describen una ladera o suelo concretos.','Mosela o Rheingau acota el contexto fluvial, pero orientación, altitud, viento y parcela varían.','Pueblo y Bereich afinan origen; son preguntas distintas de viñedo nombrado o término de sabor.','Un viñedo nombrado identifica un sitio dentro de la jerarquía; productor y añada siguen importando.','Prädikat y términos de dulzor describen materia de cosecha o estilo dulce, no un nivel de zoom del mapa.']),
  'wine-faults':lists(
    ['A clean glass and second sample remove two common confounders before a fault diagnosis.','Competing hypotheses keep one descriptor from becoming an organism or chemical verdict.','Air and time show whether a smell is reversible, transformed or persistent; record the direction.','A second bottle tests bottle-specific contamination against a wine-wide issue.','History and confidence complete the call; state what evidence would change your diagnosis.'],
    ['Sauberes Glas und zweite Probe entfernen zwei häufige Störquellen vor der Fehlerdiagnose.','Zwei konkurrierende Hypothesen verhindern, dass ein Deskriptor zum Organismus- oder Chemieurteil wird.','Luft und Zeit zeigen, ob ein Geruch reversibel, verändert oder bleibend ist; notiere die Richtung.','Eine zweite Flasche prüft flaschenbezogene Kontamination gegen ein weinweites Problem.','Historie und Sicherheit vervollständigen das Urteil; nenne, welcher Befund es ändern würde.'],
    ['Un verre propre et une seconde bouteille écartent deux confusions fréquentes avant le diagnostic.','Deux hypothèses concurrentes empêchent un descripteur de devenir verdict sur organisme ou chimie.','Air et temps montrent si l’odeur est réversible, transformée ou persistante ; notez la direction.','Une seconde bouteille oppose contamination de bouteille et problème général du vin.','Historique et niveau de confiance complètent le diagnostic ; dites quel indice le ferait changer.'],
    ['Una copa limpia y otra muestra eliminan dos confusiones comunes antes de diagnosticar.','Dos hipótesis rivales evitan convertir un descriptor en veredicto sobre organismo o química.','Aire y tiempo muestran si el olor es reversible, transformado o persistente; registra la dirección.','Otra botella contrasta contaminación de botella con un problema general del vino.','Historial y confianza completan el diagnóstico; di qué evidencia lo cambiaría.']),
  'pairing-balance':lists(
    ['Taste wine alone first; the baseline lets the food’s direction of change become visible.','One food variable—salt, fat, acid or heat—shows a mechanism more clearly than a complete dish.','Retasting after the bite reveals whether sweetness, bitterness, heat or fruit shifted.','Change one control, such as salt or sauce acid, before rejecting the wine.','Record direction and intensity, not a universal rule; another palate or dish may behave differently.'],
    ['Verkoste den Wein zuerst allein; die Ausgangslinie macht die Veränderungsrichtung durch Speise sichtbar.','Eine Speisevariable – Salz, Fett, Säure oder Schärfe – zeigt den Mechanismus klarer als ein ganzes Gericht.','Nach dem Bissen zeigt die Rückverkostung, ob Süße, Bitterkeit, Schärfe oder Frucht wechselten.','Verändere eine Kontrolle wie Salz oder Saucensäure, bevor du den Wein ablehnst.','Notiere Richtung und Intensität statt einer Universalregel; ein anderer Gaumen oder Bissen kann anders wirken.'],
    ['Goûtez d’abord le vin seul ; cette base rend visible la direction créée par le mets.','Une variable alimentaire — sel, gras, acidité ou chaleur — montre mieux le mécanisme qu’un plat entier.','Regouter après la bouchée révèle les changements de douceur, amertume, chaleur ou fruit.','Changez un contrôle, comme sel ou acidité de sauce, avant de rejeter le vin.','Notez direction et intensité plutôt qu’une règle universelle ; un autre palais ou plat peut différer.'],
    ['Prueba primero el vino solo; esa base hace visible la dirección que crea la comida.','Una variable del alimento —sal, grasa, acidez o picante— muestra mejor el mecanismo que un plato entero.','Volver a probar tras el bocado revela cambios de dulzor, amargor, calor o fruta.','Cambia un control, como sal o acidez de salsa, antes de rechazar el vino.','Registra dirección e intensidad, no una regla universal; otro paladar o plato puede comportarse distinto.']),
  'build-a-tasting-note':lists(
    ['Context and condition make an opening note repeatable: temperature, glass, time and food belong beside descriptors.','Move from broad aroma family to precise reference without turning a guess into a fact.','Describe structure across the sip—sweetness, acid, tannin, body and finish—before preference.','Track what changes after ten minutes, food or a different temperature; change is evidence.','Separate inference from preference, then write one uncertainty and one action for the next tasting.'],
    ['Kontext und Zustand machen die Anfangsnotiz wiederholbar: Temperatur, Glas, Zeit und Essen gehören neben Deskriptoren.','Gehe von der breiten Aromafamilie zur präzisen Referenz, ohne eine Vermutung zur Tatsache zu machen.','Beschreibe Struktur über den Schluck – Süße, Säure, Tannin, Körper und Nachhall – vor der Vorliebe.','Verfolge, was sich nach zehn Minuten, Essen oder anderer Temperatur ändert; Veränderung ist Evidenz.','Trenne Deutung von Vorliebe und notiere eine Unsicherheit sowie eine Handlung für die nächste Verkostung.'],
    ['Contexte et condition rendent la note initiale répétable : température, verre, temps et nourriture accompagnent les descripteurs.','Passez de la famille aromatique à la référence précise sans transformer une hypothèse en fait.','Décrivez la structure pendant la gorgée — douceur, acidité, tanin, corps et finale — avant la préférence.','Suivez ce qui change après dix minutes, avec un plat ou une autre température ; le changement est un indice.','Séparez inférence et préférence, puis notez une incertitude et une action pour la prochaine dégustation.'],
    ['Contexto y estado hacen repetible la nota inicial: temperatura, copa, tiempo y comida acompañan los descriptores.','Pasa de familia aromática amplia a referencia precisa sin convertir una suposición en hecho.','Describe estructura durante el sorbo —dulzor, acidez, tanino, cuerpo y final— antes de la preferencia.','Sigue qué cambia tras diez minutos, comida o temperatura distinta; el cambio es evidencia.','Separa inferencia y preferencia y anota una incertidumbre y una acción para la próxima cata.']),
  'producer-story-chain':lists(
    ['Place and constraint explain why a producer faced a choice; they do not prove the sensory result.','A decision point identifies the actual action—harvest, vessel, blend or release—instead of a marketing adjective.','The glass is a hypothesis test: look for the promised effect and name competing causes.','A source and its uncertainty keep the story verifiable rather than biographical decoration.','The next comparison—vintage, neighbour or opposite method—turns the story into a portable question.'],
    ['Ort und Einschränkung erklären die Wahl des Erzeugers, beweisen aber nicht das sensorische Ergebnis.','Ein Entscheidungspunkt benennt die Handlung – Lese, Gefäß, Verschnitt oder Freigabe – statt eines Werbeworts.','Das Glas prüft eine Hypothese: suche die behauptete Folge und nenne konkurrierende Ursachen.','Quelle und Unsicherheit halten die Geschichte überprüfbar statt biografischer Dekoration.','Der nächste Vergleich – Jahrgang, Nachbar oder Gegenmethode – macht die Geschichte zu einer tragbaren Frage.'],
    ['Lieu et contrainte expliquent le choix du producteur sans prouver le résultat sensoriel.','Le point de décision nomme l’action — vendange, contenant, assemblage ou sortie — plutôt qu’un adjectif marketing.','Le verre teste une hypothèse : cherchez l’effet annoncé et nommez les causes concurrentes.','Source et incertitude rendent le récit vérifiable, non décoratif.','Le prochain comparatif — millésime, voisin ou méthode opposée — transforme le récit en question transportable.'],
    ['Lugar y restricción explican la elección del productor, pero no prueban el resultado sensorial.','El punto de decisión nombra la acción —vendimia, recipiente, mezcla o salida— en vez de un adjetivo comercial.','La copa prueba una hipótesis: busca el efecto anunciado y nombra causas alternativas.','Fuente e incertidumbre mantienen verificable el relato, no solo decorativo.','El siguiente contraste —añada, vecino o método opuesto— convierte el relato en una pregunta portátil.']),
  fermentation:lists(
    ['Must analysis and inoculation set the starting conditions; measurement prevents a false diagnosis later.','Adaptation and growth reveal whether yeast is establishing under the current temperature and nutrients.','Fast conversion produces measurable sugar loss and heat; track both rather than surface bubbles.','Late-fermentation stress can slow yeast through ethanol, nutrients, temperature or inhibitors; check causes before treatment.','Dryness and stability require residual-sugar and microbial checks; a quiet surface is not proof of safety.'],
    ['Mostanalyse und Beimpfung setzen die Ausgangsbedingungen; Messung verhindert später eine falsche Diagnose.','Anpassung und Wachstum zeigen, ob sich die Hefe bei aktueller Temperatur und Nährstofflage etabliert.','Schneller Zuckerabbau erzeugt messbaren Verlust und Wärme; verfolge beides statt Oberflächenblasen.','Stress am Gärende kann Hefe durch Ethanol, Nährstoffe, Temperatur oder Hemmstoffe bremsen; prüfe Ursachen vor Behandlung.','Trockenheit und Stabilität brauchen Restzucker- und Mikrobiologiekontrollen; eine ruhige Oberfläche beweist keine Sicherheit.'],
    ['Analyse du moût et inoculation fixent les conditions de départ ; la mesure évite un faux diagnostic.','Adaptation et croissance montrent si les levures s’installent sous la température et la nutrition présentes.','Une conversion rapide produit perte de sucre et chaleur mesurables ; suivez les deux plutôt que les bulles.','Le stress de fin peut ralentir les levures par éthanol, nutriments, température ou inhibiteurs ; cherchez la cause avant le traitement.','Sécheresse et stabilité exigent contrôles des sucres résiduels et des microbes ; une surface calme ne prouve rien.'],
    ['El análisis del mosto y la inoculación fijan condiciones iniciales; medir evita un diagnóstico falso.','Adaptación y crecimiento muestran si la levadura se establece con la temperatura y nutrición actuales.','La conversión rápida produce pérdida de azúcar y calor medibles; sigue ambos datos, no solo burbujas.','El estrés final puede frenar la levadura por etanol, nutrientes, temperatura o inhibidores; busca causa antes de tratar.','Sequedad y estabilidad requieren revisar azúcar residual y microbios; una superficie quieta no prueba seguridad.']),
}

const translatedFeedback:Record<string,Localized<string[]>>={
  'wine-as-system':lists(['Bubbles are incomplete evidence; gas can stop while sugar or instability remains.','Density, heat and residual sugar separate conversion, temperature and completion.','A grape name cannot verify microbial activity or bottle stability.'],['Blasen sind unvollständige Evidenz; Gas kann nachlassen, während Zucker oder Instabilität bleiben.','Dichte, Wärme und Restzucker trennen Umwandlung, Temperatur und Abschluss.','Eine Rebsorte belegt weder mikrobielle Aktivität noch Flaschenstabilität.'],['Les bulles ne suffisent pas ; le gaz peut cesser alors que sucre ou instabilité restent.','Densité, chaleur et sucres résiduels distinguent conversion, température et fin de fermentation.','Un cépage ne vérifie ni activité microbienne ni stabilité en bouteille.'],['Las burbujas no bastan; el gas puede parar mientras quedan azúcar o inestabilidad.','Densidad, calor y azúcar residual separan conversión, temperatura y finalización.','El nombre de una variedad no verifica actividad microbiana ni estabilidad en botella.']),
  'structure-not-flavour':lists(['A first aroma does not describe the time-course of structure.','A structure map makes the comparison shareable before preference takes over.','Alcohol contributes weight but cannot stand in for the whole shape.'],['Ein erster Duft beschreibt den zeitlichen Strukturverlauf nicht.','Eine Strukturkarte macht den Vergleich teilbar, bevor Vorliebe übernimmt.','Alkohol trägt zum Gewicht bei, ersetzt aber nicht die ganze Form.'],['Un premier arôme ne décrit pas l’évolution de la structure.','Une carte de structure rend la comparaison partageable avant la préférence.','L’alcool contribue au poids sans résumer toute la forme.'],['Un primer aroma no describe la evolución de la estructura.','Un mapa de estructura hace compartible la comparación antes de la preferencia.','El alcohol aporta peso, pero no resume toda la forma.']),
  'red-white-rose':lists(['Long contact extracts colour and phenolics; it is not the direct route to pale rosé.','Contact time and separation determine how much colour and grip enter before fermentation choices add texture.','Blending is a separate legal and stylistic route, not the defining explanation for classic rosé.'],['Langer Kontakt extrahiert Farbe und Phenole; er führt nicht direkt zu blassem Rosé.','Kontaktzeit und Trennung bestimmen Farbe und Griff, bevor die Gärung Textur ergänzt.','Verschnitt ist ein eigener rechtlicher und stilistischer Weg, nicht die Erklärung für klassischen Rosé.'],['Un long contact extrait couleur et phénols ; ce n’est pas la voie directe vers un rosé pâle.','Temps de contact et séparation déterminent couleur et prise avant que la fermentation ajoute de la texture.','L’assemblage est une voie légale et stylistique distincte, pas l’explication du rosé classique.'],['El contacto largo extrae color y fenoles; no es la ruta directa hacia un rosado pálido.','Tiempo de contacto y separación determinan color y agarre antes de que la fermentación añada textura.','El ensamblaje es una vía legal y estilística distinta, no la explicación del rosado clásico.']),
  'vine-anatomy':lists(['Roots supply water and minerals; leaves do the photosynthetic work.','Stomatal behaviour links water status, gas exchange and vine growth.','Permanent wood stores and transports; it does not make berries independent of the canopy.'],['Wurzeln liefern Wasser und Mineralien; Blätter leisten Photosynthese.','Spaltöffnungen verbinden Wasserstatus, Gasaustausch und Wachstum.','Dauerholz speichert und transportiert; es macht Beeren nicht unabhängig von der Laubwand.'],['Les racines fournissent eau et minéraux ; les feuilles assurent la photosynthèse.','Le comportement des stomates relie état hydrique, échanges gazeux et croissance.','Le bois permanent stocke et transporte ; il ne rend pas les baies indépendantes du feuillage.'],['Las raíces aportan agua y minerales; las hojas hacen la fotosíntesis.','Los estomas conectan estado hídrico, intercambio gaseoso y crecimiento.','La madera permanente almacena y transporta; no independiza las bayas de la vegetación.']),
  'ripeness-harvest':lists(['Brix is a proxy and sampling error can outweigh a daily change.','Harvest is a style-and-risk decision: sample, taste tissues, test chemistry and read weather together.','More hang time can gain flavour while losing crop or freshness to weather and disease.'],['Brix ist ein Näherungswert; Probenfehler können eine Tagesänderung überwiegen.','Lese ist eine Stil- und Risikoentscheidung: Probe, Gewebe, Chemie und Wetter gehören zusammen.','Längeres Hängen kann Aroma gewinnen, aber durch Wetter und Krankheit Ertrag oder Frische verlieren.'],['Le Brix est un indice ; l’erreur d’échantillonnage peut dépasser une variation quotidienne.','La vendange est une décision de style et de risque : échantillon, tissus, chimie et météo vont ensemble.','Attendre peut gagner en arômes mais perdre récolte ou fraîcheur par météo et maladie.'],['Brix es un indicador y el error de muestreo puede superar un cambio diario.','La vendimia es una decisión de estilo y riesgo: muestra, tejidos, química y clima van juntos.','Esperar puede ganar aroma, pero perder cosecha o frescura por clima y enfermedad.']),
  'germany-origin':lists(['A Prädikat is not a map zoom level.','The label can combine origin, named place and ripeness or taste category without collapsing them.','Slope changes exposure and work; it cannot guarantee a sensory or quality outcome.'],['Ein Prädikat ist keine Kartenzoomstufe.','Das Etikett kann Herkunft, Lage und Reife- oder Geschmackskategorie verbinden, ohne sie gleichzusetzen.','Hanglage verändert Exposition und Arbeit; sie garantiert kein sensorisches oder Qualitätsresultat.'],['Un Prädikat n’est pas un niveau de zoom cartographique.','L’étiquette peut combiner origine, lieu nommé et catégorie de maturité ou de goût sans les confondre.','La pente change exposition et travail ; elle ne garantit ni sensation ni qualité.'],['Un Prädikat no es un nivel de zoom del mapa.','La etiqueta puede combinar origen, lugar y categoría de madurez o sabor sin confundirlos.','La pendiente cambia exposición y trabajo; no garantiza resultado sensorial ni calidad.']),
  'wine-faults':lists(['A descriptor is evidence, not an organism or concentration.','Controls, time and a second sample distinguish reduction, oxidation, contamination and volatile phenols more safely.','Air is a test; some sulfur compounds transform while others persist or worsen.'],['Ein Deskriptor ist Evidenz, kein Organismus- oder Konzentrationsnachweis.','Kontrollen, Zeit und zweite Probe trennen Reduktion, Oxidation, Kontamination und Phenole sicherer.','Luft ist ein Test; manche Schwefelstoffe wandeln sich, andere bleiben oder verschlimmern sich.'],['Un descripteur est un indice, pas un organisme ni une concentration.','Contrôles, temps et seconde bouteille distinguent plus sûrement réduction, oxydation, contamination et phénols volatils.','L’air est un test ; certains composés soufrés évoluent, d’autres persistent ou s’aggravent.'],['Un descriptor es evidencia, no un organismo ni una concentración.','Controles, tiempo y segunda muestra distinguen mejor reducción, oxidación, contaminación y fenoles volátiles.','El aire es una prueba; algunos azufrados cambian y otros persisten o empeoran.']),
  'pairing-balance':lists(['Heat and fruit can shift perception, but sweetness is the clean first variable to test.','Relative sweetness is a balance condition; a controlled second bite makes the direction observable.','Pairing effects are contextual, not absent.'],['Schärfe und Frucht verschieben Wahrnehmung, doch Süße ist die klare erste Variable.','Relative Süße ist eine Balancebedingung; ein kontrollierter zweiter Bissen macht die Richtung sichtbar.','Pairingeffekte sind kontextabhängig, nicht abwesend.'],['Chaleur et fruit peuvent déplacer la perception, mais la douceur est la première variable nette à tester.','La douceur relative conditionne l’équilibre ; une seconde bouchée contrôlée rend la direction observable.','Les effets d’accord dépendent du contexte, ils ne sont pas absents.'],['Picante y fruta cambian la percepción, pero el dulzor es la primera variable clara que probar.','El dulzor relativo condiciona el equilibrio; un segundo bocado controlado hace visible la dirección.','Los efectos del maridaje dependen del contexto, no están ausentes.']),
  'build-a-tasting-note':lists(['Descriptors without context are difficult to compare later.','A useful note records conditions, structure, change, uncertainty and the next action.','A score hides the evidence that makes a future tasting comparable.'],['Deskriptoren ohne Kontext lassen sich später schwer vergleichen.','Eine brauchbare Notiz hält Bedingungen, Struktur, Veränderung, Unsicherheit und nächste Handlung fest.','Eine Punktzahl verbirgt die Evidenz für einen späteren Vergleich.'],['Des descripteurs sans contexte se comparent mal plus tard.','Une note utile garde conditions, structure, évolution, incertitude et action suivante.','Une note chiffrée cache les indices qui rendent une dégustation future comparable.'],['Los descriptores sin contexto se comparan mal después.','Una nota útil registra condiciones, estructura, cambio, incertidumbre y siguiente acción.','Una puntuación oculta la evidencia que permite comparar una cata futura.']),
  'producer-story-chain':lists(['Biography first can create expectation before evidence.','A reveal ladder lets the room test each claim and keeps the maker’s constraint meaningful.','Leading with an aroma turns a hypothesis into a demand.'],['Biografie zuerst kann Erwartungen vor der Evidenz erzeugen.','Eine Enthüllungsleiter lässt die Runde jede Behauptung prüfen und hält die Einschränkung des Erzeugers bedeutsam.','Ein vorgegebenes Aroma macht aus einer Hypothese eine Erwartung.'],['La biographie d’abord crée une attente avant les indices.','Une révélation graduée permet de tester chaque affirmation et garde la contrainte du vigneron significative.','Imposer un arôme transforme une hypothèse en consigne.'],['La biografía primero crea expectativa antes de la evidencia.','Una revelación gradual permite probar cada afirmación y mantiene significativa la restricción del productor.','Dar un aroma por adelantado convierte una hipótesis en exigencia.']),
  fermentation:lists(['Heat may help or harm; without diagnosis it is an uncontrolled change.','A stalled ferment is a diagnosis problem: measurement and multiple constraints come before a remedy.','Nitrogen can be limiting, but blind additions ignore timing, dose, legal limits and other inhibitors.'],['Wärme kann helfen oder schaden; ohne Diagnose ist sie eine unkontrollierte Änderung.','Eine stockende Gärung ist ein Diagnoseproblem: Messung und mehrere Faktoren kommen vor dem Mittel.','Stickstoff kann limitieren, aber blinde Zugaben ignorieren Zeitpunkt, Dosis, Rechtsgrenzen und andere Hemmstoffe.'],['La chaleur peut aider ou nuire ; sans diagnostic, c’est une modification incontrôlée.','Une fermentation bloquée est un problème de diagnostic : mesure et contraintes précèdent le remède.','L’azote peut limiter, mais un ajout aveugle ignore moment, dose, limites légales et autres inhibiteurs.'],['El calor puede ayudar o dañar; sin diagnóstico es un cambio sin control.','Una fermentación parada es un problema de diagnóstico: medir y revisar varias condiciones precede al remedio.','El nitrógeno puede limitar, pero añadirlo a ciegas ignora momento, dosis, límites legales y otros inhibidores.']),
}

