function interactionFor(profile:EditorialProfile):InteractionSeed{
  const seed=interactionSeeds[profile.id]
  return {...seed,feedback:translatedFeedback[profile.id],states:controlStates[profile.id],outcomes:stageOutcomes[profile.id],prompts:promptSet(interactionFocus[profile.id],mapFocus[profile.id]??interactionFocus[profile.id],stageFocus[profile.id]??interactionFocus[profile.id])}
}
function bodyFor(profile:EditorialProfile,index:number):Localized<string[]>{
  return Object.fromEntries(locales.map(locale=>{
    const notes=profile.notes[locale]
    return [locale,[notes[(index*2)%notes.length],notes[(index*2+1)%notes.length],notes[(index*2+2)%notes.length]]]
  })) as Localized<string[]>
}
function authoredBlockTitle(profile:EditorialProfile,kind:LearningBlockKind):Localized<string>{
  const suffix={en:{table:'At the table',check:'Check the mechanism',terms:'Terms to use',links:'Connected examples',sources:'Check the evidence'},de:{table:'Am Tisch',check:'Den Mechanismus prüfen',terms:'Begriffe zum Einordnen',links:'Verbundene Beispiele',sources:'Evidenz prüfen'},fr:{table:'À table',check:'Vérifier le mécanisme',terms:'Mots à mobiliser',links:'Exemples reliés',sources:'Vérifier les indices'},es:{table:'En la mesa',check:'Comprobar el mecanismo',terms:'Términos para usar',links:'Ejemplos conectados',sources:'Comprobar la evidencia'}} as const
  return Object.fromEntries(locales.map(locale=>{
    const stages=profile.stages[locale],first=stages[0],last=stages.at(-1)??first,copy=suffix[locale]
    const title=kind==='process-timeline'?`${first} → ${last}`
      :['comparison-lab','sensory-lab','simulator'].includes(kind)?profile.control.label[locale]
      :kind==='annotated-plate'?`${profile.title[locale]}: ${first}`
      :kind==='map-lab'?`${profile.title[locale]}: ${stages[Math.min(2,stages.length-1)]}`
      :kind==='decision-case'?`${first}: ${stages[1]??last}`
      :kind==='tasting-prompt'?`${profile.title[locale]} · ${copy.table}`
      :kind==='knowledge-check'?`${profile.title[locale]} · ${copy.check}`
      :kind==='glossary'?`${profile.title[locale]} · ${copy.terms}`
      :kind==='entity-connections'?copy.links
      :kind==='sources'?copy.sources
      :profile.question[locale]
    return [locale,title]
  })) as Localized<string>
}
function knowledgeOptions(profile:EditorialProfile):Localized<string[]>{
  return interactionFor(profile).choices
}
function makeBlock(profile:EditorialProfile,index:number,kind:LearningBlockKind):LearningBlock{
  const labels=blockLabels[kind]
  const seed=interactionFor(profile)
  const options=kind==='knowledge-check'?knowledgeOptions(profile):undefined
  const depth=lessonDepthByModule[profile.id]
  const reading=depth&&index<8?Object.fromEntries(locales.map(locale=>[locale,[depth[locale][index]]])) as Localized<string[]>:undefined
  const generatedBody=bodyFor(profile,index)
  const stageBody=seed.outcomes??generatedBody
  const body=kind==='process-timeline'||kind==='decision-case'?stageBody:kind==='annotated-plate'?Object.fromEntries(locales.map(locale=>[locale,stageBody[locale].slice(0,3)])) as Localized<string[]>:kind==='map-lab'?Object.fromEntries(locales.map(locale=>[locale,stageBody[locale].slice(0,4)])) as Localized<string[]>:generatedBody
  const interaction=interactiveKinds.includes(kind)?{prompt:kind==='knowledge-check'?seed.prompt:seed.prompts?.[kind as InteractionKind]??seed.prompt,feedback:seed.feedback,labels:Object.fromEntries(locales.map(locale=>[locale,profile.stages[locale].slice(0,kind==='decision-case'?5:3)])) as Localized<string[]>}:undefined
  const media=mediaKinds.includes(kind)?lessonMediaByBlock[profile.id]?.[kind]:undefined
  return {id:`${profile.id}--${kind}-${index}`,kind,title:authoredBlockTitle(profile,kind),eyebrow:labels.eyebrow,body,reading,duration:kind==='sources'?3:kind==='knowledge-check'?4:6,behavior:kind==='decision-case'?'host-reveal':kind==='sources'?'self-paced':'host-or-self',linkedEntityIds:profile.entities,
    media:media?{...media,focus:profile.archetype}:undefined,
    options,interaction,answer:kind==='knowledge-check'?1:undefined,stages:profile.stages,control:{...profile.control,states:seed.states??lists([])},sources:kind==='sources'?profile.sources:undefined}
}
function makeModule(profile:EditorialProfile):LearningModule{
  const kinds:LearningBlockKind[]=[...patterns[profile.archetype],'glossary','entity-connections','sources']
  return {id:profile.id,school:profile.school,title:profile.title,question:profile.question,summary:Object.fromEntries(locales.map(locale=>[locale,profile.notes[locale][0]])) as Localized<string>,level:profile.level,minutes:48,archetype:profile.archetype,
    outcomes:Object.fromEntries(locales.map(locale=>[locale,profile.notes[locale].slice(1,4)])) as Localized<string[]>,experiment:Object.fromEntries(locales.map(locale=>[locale,profile.notes[locale][4]])) as Localized<string>,blocks:kinds.map((kind,index)=>makeBlock(profile,index,kind)),entityIds:profile.entities}
}

export const learningModules:LearningModule[]=profiles.map(makeModule)
export const learningModuleById=(id:string)=>learningModules.find(module=>module.id===id)
export const learningBlockById=(id:string)=>learningModules.flatMap(module=>module.blocks.map(block=>({module,block}))).find(item=>item.block.id===id)
export const curriculumSources:Record<LearningSchool,{label:string;url:string}[]>=Object.fromEntries(Object.keys(schoolCopy).map(school=>[school,profiles.filter(profile=>profile.school===school).flatMap(profile=>profile.sources.map(({label,url})=>({label,url})))])) as Record<LearningSchool,{label:string;url:string}[]>

function words(value:string){return value.match(/[\p{L}\p{N}]+(?:[-’'][\p{L}\p{N}]+)*/gu)?.length??0}
function trigrams(value:string){const tokens=(value.toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu)??[]);return new Set(tokens.slice(0,-2).map((token,index)=>`${token} ${tokens[index+1]} ${tokens[index+2]}`))}
function similarity(a:Set<string>,b:Set<string>){let common=0;for(const value of a)if(b.has(value))common++;return common/Math.max(1,a.size+b.size-common)}
export function learningValidation(){
  const issues:string[]=[],ids=new Set<string>(),blockIds=new Set<string>()
  for(const module of learningModules){
    if(ids.has(module.id))issues.push(`duplicate module ${module.id}`);ids.add(module.id)
    const visuals=module.blocks.flatMap(block=>block.media?.src?[block.media.src]:[])
    if(new Set(visuals).size!==visuals.length)issues.push(`${module.id} repeats a visual`)
    const depth=lessonDepthByModule[module.id]
    if(!depth)issues.push(`missing lesson depth ${module.id}`)
    for(const locale of locales){
      const reading=module.blocks.flatMap(block=>block.reading?.[locale]??[])
      const unique=[...new Set(reading.map(paragraph=>paragraph.trim()).filter(Boolean))]
      if(reading.length!==8)issues.push(`${module.id} ${locale} has ${reading.length} authored reading paragraphs; expected 8`)
      if(unique.length!==reading.length)issues.push(`${module.id} ${locale} repeats authored reading paragraphs`)
      const count=words(unique.join(' '))
      if(count<800)issues.push(`${module.id} ${locale} has ${count} authored reading words; minimum 800`)
      if(depth&&JSON.stringify(depth[locale])!==JSON.stringify(reading))issues.push(`${module.id} ${locale} authored reading is not wired to its depth source`)
    }
    for(const block of module.blocks){if(blockIds.has(block.id))issues.push(`duplicate block ${block.id}`);blockIds.add(block.id)}
  }
  for(const id of Object.keys(lessonDepthByModule))if(!ids.has(id))issues.push(`lesson depth ${id} has no curriculum module`)
  for(const locale of locales)for(let i=0;i<learningModules.length;i++)for(let j=i+1;j<learningModules.length;j++){
    const text=(module:LearningModule)=>module.blocks.flatMap(block=>block.body[locale]).join(' '),score=similarity(trigrams(text(learningModules[i])),trigrams(text(learningModules[j])))
    if(score>.34)issues.push(`content similarity ${locale} ${learningModules[i].id}/${learningModules[j].id}: ${score.toFixed(2)}`)
  }
  return {modules:learningModules.length,schools:new Set(learningModules.map(module=>module.school)).size,archetypes:new Set(learningModules.map(module=>module.archetype)).size,issues}
}
